mapper.update:
UPDATE t_risk_config
SET stop_out_level = #{stopOutLevel}, margin_call_level = #{marginCallLevel}
WHERE symbol IS NULL

mapper.delete:
DELETE FROM t_account
WHERE user_id = #{userId}
  AND currency = #{currency}

